from concurrent.futures import ThreadPoolExecutor

import pytest


def parity(x: int) -> int:
    return x % 2


def parities(xs: list[int]) -> list[int]:
    """Parity (0 or 1) of each element of xs, computed in parallel with a
    thread pool. The result is in input order, regardless of worker count
    or task completion order. Does not modify xs."""
    with ThreadPoolExecutor() as pool:
        return list(pool.map(parity, xs))


def test_parities_basic() -> None:
    assert parities([1, 2, 3, 4]) == [1, 0, 1, 0]


def test_parities_empty() -> None:
    assert parities([]) == []


def test_parities_single() -> None:
    assert parities([7]) == [1]
    assert parities([0]) == [0]


def test_parities_negative() -> None:
    assert parities([-3, -2, -1, 0]) == [1, 0, 1, 0]


def test_parities_large_ints() -> None:
    big = 10**30
    assert parities([big, big + 1, -big - 1]) == [0, 1, 1]


def test_parities_preserves_order_large_input() -> None:
    xs = list(range(5000))
    assert parities(xs) == [x % 2 for x in xs]


def test_parities_order_not_input_sorted() -> None:
    xs = [9, 4, 4, 7, 0, 3, 8, 1, 1, 2]
    assert parities(xs) == [parity(x) for x in xs]


def test_parities_deterministic_across_calls() -> None:
    xs = [(i * 7919) % 1009 for i in range(2000)]
    expected = [parity(x) for x in xs]
    for _ in range(5):
        assert parities(xs) == expected


def test_parities_does_not_mutate_input() -> None:
    xs = [5, 6, 7]
    copy = list(xs)
    parities(xs)
    assert xs == copy


def test_parities_returns_new_list() -> None:
    xs = [0, 1]
    out = parities(xs)
    assert out is not xs


def test_parities_values_are_ints_0_or_1() -> None:
    out = parities(list(range(-50, 50)))
    assert all(type(p) is int and p in (0, 1) for p in out)


def test_parities_propagates_errors(monkeypatch: pytest.MonkeyPatch) -> None:
    import sys

    mod = sys.modules[parities.__module__]

    def boom(x: int) -> int:
        if x == 3:
            raise ValueError("bad")
        return x % 2

    if not hasattr(mod, "parity"):
        pytest.skip("parity not looked up from module namespace")
    monkeypatch.setattr(mod, "parity", boom)
    with pytest.raises(ValueError):
        parities([1, 2, 3, 4])
